head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > importFormatter]<br/>XML 또는 JSON 형식으로 Row 데이터를 설정할때 적용될 데이터 변환 사용자 정의 함수를 설정합니다.",
    "validation" : [        
		"useNull=true 인 경우 반환값으로 null 을 사용할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };    

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strGridView = '';
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성
    strTarget += '<w2:dataList ' + strNameSpace + ' useNull="true" id="target1" baseNode="list" repeatNode="map">';        
    strTarget += '<w2:columnInfo>';
    strTarget += '<w2:column id="col1" name="name1" dataType="text" importFormatter="scwin.fn_importFormatter"></w2:column>';
    strTarget += '<w2:column id="col2" name="name2" dataType="text" ></w2:column>';
    strTarget += '</w2:columnInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '<w2:row>';
    strTarget += '<col1><![CDATA[initData1]]></col1>';    
    strTarget += '<col2><![CDATA[initData2]]></col2>';    
    strTarget += '</w2:row>';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataList>';     

    $p.data.create(strTarget);

    // gridView 생성    
    strGridView += '<w2:gridView ' + strNameSpace + ' dataList="data:target1" rowStatusVisible="true" checkAllType="false" id="" style="width:500px;height:300px;">';
    strGridView += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strGridView += '<w2:header style="" id="header1">';
    strGridView += '<w2:row style="" id="row1">';
    strGridView += '<w2:column width="180" style="" inputType="text" id="column1" value="importFormatter 설정"></w2:column>';
    strGridView += '<w2:column width="180" style="" inputType="text" id="column2" value="importFormatter 미설정"></w2:column>';
    strGridView += '</w2:row>';
    strGridView += '</w2:header>';
    strGridView += '<w2:gBody style="" id="gBody1">';
    strGridView += '<w2:row style="" id="row2">';
    strGridView += '<w2:column width="70" style="" inputType="text" id="col1" value=""></w2:column>';
    strGridView += '<w2:column width="70" style="" inputType="text" id="col2" value=""></w2:column>';
    strGridView += '</w2:row>';
    strGridView += '</w2:gBody>';
    strGridView += '</w2:gridView>';    

    scwin["gridView1"] = await $p.dynamicCreate(
        "gridView1",
        "gridView",
        strGridView,
        grp_comp
    );    

    scwin.btn_getAllJSON_onclick();
}



scwin.btn_getAllJSON_onclick = function (e) {
    let rtn = target1.getAllJSON();
    let jsonString = JSON.stringify(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);
};



// 사용자 정의 함수
scwin.fn_importFormatter = function (rowData, rowIdx, colInfo) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====사용자 정의 함수 실행=====");
    wf_body_bottom.getObj("scwin").setReturnValue("rowData : " + rowData);
    wf_body_bottom.getObj("scwin").setReturnValue("rowData.col1 : " + rowData.col1);
    wf_body_bottom.getObj("scwin").setReturnValue("rowData.col2 : " + rowData.col2);
    wf_body_bottom.getObj("scwin").setReturnValue("rowIdx : " + rowIdx);
    wf_body_bottom.getObj("scwin").setReturnValue("colInfo : " + colInfo);

    return null;
};
